// === Tab: Particle ===
class Particle {
	constructor(x, y, dst = 5) {
		this.pos = createVector(x, y, 0);
		this.dst = dst;
		this.finished = false;
		this.path = [];
		this.resetCooldown();
	}

	resetCooldown() {
		this.cooldown = 100;
	}

	update(t, points) {
		if (this.finished) return;

		this.cooldown--;
		if (this.cooldown < 0) {
			this.finished = true;
			return;
		}

		let n = (noise(this.pos.x*0.01, this.pos.y*0.01)*6) % TWO_PI;

    // Magic - aka "Constrains The number of directions the noise value can have"
	  let m = 3                 // M for Marvellously-Majestic-Magnificient-Modifying-Magic

		m=16
		const rad = max(width, height) * 0.55;
		const distance = max(1, dist(this.pos.x, this.pos.y, width/2, height/2))
		if (distance >= rad) m = 1.1
		if (distance > rad/2 && distance < rad) m = 3.3
		if (distance > 0 && distance <= rad/2) m = 16

		const maxDist = max(width, height) * 0.45;
		const maxM = 5;
		m = constrain(Math.sqrt(map(distance, 0, maxDist, maxM * maxM, 1)), 1, maxM);
		if (distance > maxDist) m = 1.1;


		let a = TWO_PI/m          // Change direction
    let b = round(n/TWO_PI*m) // Round the value
    n = a * b;                // New direction

    // Moving the points -> because we use trigonometry we can use cos and sin to move
    // To make it move faster you can multiple the values
    // Swaping cos/sin and reversing the sign (+ to - or - to +) rotates where they move
	  const newPos = this.pos.copy().add(
			cos(n) * random(1, 8), 
			sin(n) * random(1, 4), 
			0
		);

    // color index
		newPos.z = 1;
	  if (n - m/2 > 1) newPos.z = 0;

		// return when oob
		if (newPos.x < 0 || newPos.x > width || newPos.y < 0 || newPos.y > height) {
			this.finished = true;
			return;
		}



		// return by probability
		if (random(255) > t) return;

		// return, when other point nearby -> expensive function
		for (const pts of points) {
			for (const pt of pts.path) {
				const dx = abs(newPos.x - pt.x);
				const dy = abs(newPos.y - pt.y);
				if (dx + dy < this.dst) {
					return;
				}
			}
		}

		// store position
		this.path.push(newPos);

		// this.show();
		stroke(pal[newPos.z]);
		line(this.pos.x, this.pos.y, newPos.x, newPos.y);
		polys[newPos.z].addPtsArr([new Point(this.pos.x, this.pos.y), new Point(newPos.x, newPos.y)]);
		this.pos = newPos.copy();
		this.resetCooldown();
	}

	show() {
		stroke(255, 160);
		circle(this.pos.x, this.pos.y, 5);
		return;

		if (this.path.length < 1) return;
		const lastPos = this.path[this.path.length-1];
		stroke(pal[lastPos.z]);
		circle(lastPos.x, lastPos.y, 2);
	}

}

