// see: https://github.com/epibyte/p5-epi-shapesvg
var { Point, Line, Polygon } = EpiShapeSvg;
var pal, polys;
var particles = []
var n = 500 // can be adaptative using canvas width/height
var   t = 0

function setup() {
  createCanvas(windowWidth,windowHeight);
	background(212) ;
	noFill();

	pal = ["darkred", "navy"];
	polys = [];
	for (let i=0; i<pal.length; i++) {
		polys[i] = new Polygon();
	}

  for (i=0; i<n; i++) {  
		particles[i] = new Particle(random(width), random(height), 5)  
	}

	loop();
}

function draw() {
	// if (frameCount === 1000) console.log(particles);

	for (let p of particles) {
		p.update(t, particles); // move and check for no overlapping
		// if (p === particles[0]) p.show(); // not neccesary, will be drawn in update when newPos stored
  }

	fill(212); noStroke();
	rect(0, 0, 300, 10);
	fill(32);
	const finished = particles.reduce((sum, particle) => {
    return particle.finished ? sum + 1 : sum;
	}, 0);
	const total = particles.reduce((sum, particle) => {
    return sum + particle.path.length;
	}, 0);
	text("" + finished + "/" + particles.length + " " + total, 2, 10);
	noFill();

	if (finished === particles.length) {
		// noLoop() removed for animation
	}

  t += 1; 
}

function doubleClicked() {
	setup();
}

function keyPressed() {
	if (key === "s") saveSvg("epi_noise_ang.svg.txt");
}

function saveSvg(file_name) {
	console.log("save svg");

	let svgAll = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n`;
	for (let i=0; i<pal.length; i++) {
		polys[i].optimize();
		svgAll += `<g stroke="${pal[i]}" fill="none">\n${polys[i].toSVG()}</g>\n`;
	}
	svgAll += `</svg>`;

	save(svgAll.split("\n"), file_name);
}
